<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>3D Rotating Logo</title>
<style>
  :root {
    --viz-text: #e8eaf0;
    --viz-muted: #8a8fa3;
    --viz-panel: #0f1117;
    --viz-card: #1a1d27;
    --viz-border: #2a2e3a;
    --viz-accent: #6c8cff;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: var(--viz-panel);
    color: var(--viz-text);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    user-select: none;
    -webkit-user-select: none;
  }
  .hint {
    font-size: 12px;
    color: var(--viz-muted);
  }
  .scene {
    width: 220px;
    height: 220px;
    perspective: 700px;
    cursor: grab;
  }
  .scene.dragging { cursor: grabbing; }
  .cube {
    width: 100%;
    height: 100%;
    position: relative;
    transform-style: preserve-3d;
    transform: rotateX(-18deg) rotateY(24deg);
    will-change: transform;
  }
  .face {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1.5px solid var(--viz-border);
    background: var(--viz-card);
    backface-visibility: hidden;
    overflow: hidden;
  }
  .front  { transform: translateZ(110px); }
  .back   { transform: rotateY(180deg) translateZ(110px); }
  .right  { transform: rotateY(90deg) translateZ(110px); }
  .left   { transform: rotateY(-90deg) translateZ(110px); }
  .top    { transform: rotateX(90deg) translateZ(110px); }
  .bottom { transform: rotateX(-90deg) translateZ(110px); }

  .grad {
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 30% 30%, color-mix(in srgb, var(--viz-accent) 55%, transparent), transparent 60%);
    pointer-events: none;
  }
  .logo {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    gap: 6px;
    z-index: 2;
  }
  .mark {
    width: 74px;
    height: 74px;
    border-radius: 18px;
    background: linear-gradient(135deg, var(--viz-accent), color-mix(in srgb, var(--viz-accent) 40%, #000));
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 24px color-mix(in srgb, var(--viz-accent) 40%, transparent), inset 0 1px 0 rgba(255,255,255,0.25);
    font-size: 40px;
    font-weight: 800;
    color: #fff;
    letter-spacing: -1px;
  }
  .label {
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--viz-muted);
  }
  .controls {
    display: flex;
    gap: 8px;
  }
  button {
    background: var(--viz-card);
    color: var(--viz-text);
    border: 1px solid var(--viz-border);
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 12px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
  }
  button:hover { border-color: var(--viz-accent); }
  button.active { background: var(--viz-accent); color: #fff; border-color: var(--viz-accent); }
</style>
</head>
