button.small{font-size:11px;padding:4px 9px}
.hint{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);background:rgba(6,9,15,.55);backdrop-filter:blur(8px);padding:6px 12px;border-radius:8px;font-size:11px;color:var(--viz-muted);border:1px solid var(--viz-border);pointer-events:none;white-space:nowrap}
@media(max-width:720px){#panel{width:230px;font-size:11px}.hint{font-size:10px;white-space:normal;max-width:90%}}
